use WebFiori\Ai\Embedding\SqliteVectorStore;
use WebFiori\Ai\Rag\LocalRagProvider;
use WebFiori\Ai\Tool\AgentMemory;
use WebFiori\Ai\Tool\KeywordRememberStrategy;

// Create memory backed by local RAG
$rag = new LocalRagProvider(
    store: new SqliteVectorStore('/data/chatbot-memory.db'),
    embedder: $client,
);

$memory = new AgentMemory(ragProvider: $rag, minScore: 0.75, topK: 5);

// Attach to client — automatically recalls before and remembers after each chat
$client->setMemory($memory);
$client->setRememberStrategy(new KeywordRememberStrategy());

// Now the client learns from corrections:
$client->chat([Message::user('What is WebFiori routing?')]); // normal response
$client->chat([Message::user('Actually, v3 uses #[Route] attributes.')]); // auto-stored
$client->chat([Message::user('How does routing work?')]); // recalls the correction
```

