use WebFiori\Ai\Message;
use WebFiori\Ai\Routing\ModelRouter;
use WebFiori\Ai\Routing\Strategy\TaskComplexityStrategy;

$router = new ModelRouter(
    providers: ['fast' => $geminiFlash, 'smart' => $claudeSonnet],
    default: 'fast',
);

