use WebFiori\Ai\Context\SlidingWindowStrategy;
use WebFiori\Ai\Context\SummarizingWindowStrategy;
use WebFiori\Ai\Context\SummarizationPrompt;

// Option A: Sliding window (drop oldest messages)
$client->setContextWindowStrategy(new SlidingWindowStrategy(
    maxTokens: 8000,
    reserveForCompletion: 2000,
    preserveSystemMessage: true,
));

// Option B: Summarizing window (summarize old messages)
$client->setContextWindowStrategy(new SummarizingWindowStrategy(
    maxTokens: 8000,
    reserveForCompletion: 2000,
    summarizer: $client, // Uses the same provider to summarize
    prompt: new SummarizationPrompt('Summarize this conversation concisely.'),
));
