$client->setTemperatureStrategy(new TaskBasedTemperatureStrategy(
    buckets: [
        ['temperature' => 0.1, 'keywords' => ['sql', 'query', 'migrate']],
        ['temperature' => 0.5, 'keywords' => ['explain', 'summarize']],
        ['temperature' => 0.9, 'keywords' => ['brainstorm', 'creative', 'story']],
    ],
    default: 0.7,
));

// Or fixed for consistency
$client->setTemperatureStrategy(new FixedTemperatureStrategy(0.3));
