use WebFiori\Ai\Exception\AuthenticationException;
use WebFiori\Ai\Exception\RateLimitException;
use WebFiori\Ai\Exception\ProviderException;
use WebFiori\Ai\Exception\ContextOverflowException;

try {
    $response = $client->chat($messages);
} catch (AuthenticationException $e) {
    // Invalid API key or credentials
    log_error('Auth failed: ' . $e->getMessage());
} catch (RateLimitException $e) {
    // Too many requests — back off
    sleep(5);
    $response = $client->chat($messages); // Retry
} catch (ContextOverflowException $e) {
    // Messages exceed model's context window
    // Consider using SlidingWindowStrategy
} catch (ProviderException $e) {
    // General provider error (500, model not found, etc.)
    log_error('Provider error: ' . $e->getMessage());
}
